import{_ as e,o as d,c as r,a3 as a}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse(`{"title":"Entités HA pour Zendure","description":"Capteurs, champs numériques, sélecteurs, interrupteurs et boutons importants de l'intégration Zendure.","frontmatter":{"title":"Entités HA pour Zendure","description":"Capteurs, champs numériques, sélecteurs, interrupteurs et boutons importants de l'intégration Zendure."},"headers":[],"relativePath":"fr/collection/zendure-ha/entitaeten.md","filePath":"fr/collection/zendure-ha/entitaeten.md","lastUpdated":1793123358000}`),o={name:"fr/collection/zendure-ha/entitaeten.md"};function n(i,t,s,c,u,l){return d(),r("div",null,[...t[0]||(t[0]=[a('<p><a id="zendure-ha-entites"></a><a id="orientation-actuelle"></a></p><h1 id="entitaten" tabindex="-1">Entités <a class="header-anchor" href="#entitaten" aria-label="Permalink to &quot;Entités {#entitaten}&quot;">​</a></h1><p>L&#39;intégration génère des entités différentes selon l&#39;appareil. Tous les modèles ne prennent pas en charge toutes les entités.</p><h2 id="wichtige-sensoren" tabindex="-1">Capteurs importants <a class="header-anchor" href="#wichtige-sensoren" aria-label="Permalink to &quot;Capteurs importants {#wichtige-sensoren}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Entité / Traduction</th><th>Utilité</th></tr></thead><tbody><tr><td><code>Batterieladezustand (SoC)</code></td><td>Niveau de charge de la batterie (en pourcentage)</td></tr><tr><td><code>Verfügbare Energie</code></td><td>Énergie disponible au-dessus du SoC (état de charge) minimal</td></tr><tr><td><code>Gesamtkapazität Batterie</code></td><td>Capacité de batterie détectée</td></tr><tr><td><code>Solarleistung</code></td><td>Puissance d&#39;entrée solaire totale</td></tr><tr><td><code>PV1</code> à <code>PV4 Solarleistung</code></td><td>Puissance solaire des entrées individuelles</td></tr><tr><td><code>Haus-Ausgangsleistung</code></td><td>Puissance vers la maison</td></tr><tr><td><code>Netz-Eingangsleistung</code></td><td>Puissance du réseau vers l&#39;appareil</td></tr><tr><td><code>Batterieleistung</code></td><td>Puissance de charge/décharge calculée</td></tr><tr><td><code>Batterieladeleistung</code></td><td>Puissance vers la batterie</td></tr><tr><td><code>Batterieentladeleistung</code></td><td>Puissance provenant de la batterie</td></tr><tr><td><code>Verbleibende Zeit</code></td><td>Temps de charge ou de décharge calculé</td></tr><tr><td><code>Verbindungsstatus</code></td><td>Cloud, Local, zenSDK, HEMS ou groupe de fusibles (Fuse Group) manquant</td></tr><tr><td><code>BMS-Firmware</code></td><td>Firmware de la batterie</td></tr><tr><td><code>AC-Firmware</code></td><td>Firmware AC</td></tr><tr><td><code>Master-Firmware</code></td><td>Firmware maître (Master)</td></tr><tr><td><code>Roundtrip-Wirkungsgrad</code></td><td>Rapport entre l&#39;énergie déchargée et l&#39;énergie chargée</td></tr></tbody></table><h2 id="energiezahler" tabindex="-1">Compteurs d&#39;énergie <a class="header-anchor" href="#energiezahler" aria-label="Permalink to &quot;Compteurs d&#39;énergie {#energiezahler}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Entité / Traduction</th><th>Objectif</th></tr></thead><tbody><tr><td><code>Gesamte Ladeenergie</code></td><td>Énergie de charge cumulée</td></tr><tr><td><code>Gesamte Entladeenergie</code></td><td>Énergie de décharge cumulée</td></tr><tr><td><code>Gesamte Hausenergie</code></td><td>Énergie vers la maison</td></tr><tr><td><code>Gesamte Solarenergie</code></td><td>Énergie solaire produite</td></tr><tr><td><code>Gesamte Netzenergie</code></td><td>Énergie provenant du réseau</td></tr><tr><td><code>Gesamte Off-Grid-Energie</code></td><td>Énergie en mode hors réseau (Off-Grid), si pris en charge</td></tr><tr><td><code>Schaltvorgänge</code></td><td>Changement d&#39;état</td></tr></tbody></table><h2 id="zahlenfelder" tabindex="-1">Champs numériques <a class="header-anchor" href="#zahlenfelder" aria-label="Permalink to &quot;Champs numériques {#zahlenfelder}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Entité / Traduction</th><th>Objectif</th></tr></thead><tbody><tr><td><code>AC-Eingangsgrenze</code></td><td>Puissance de charge AC maximale</td></tr><tr><td><code>AC-Ausgangsgrenze</code></td><td>Puissance de sortie CA maximale</td></tr><tr><td><code>Manuelle Leistung</code></td><td>Consigne pour le mode gestionnaire manuel</td></tr><tr><td><code>SoC-Minimum</code></td><td>Limite inférieure de charge</td></tr><tr><td><code>SoC-Zielwert</code></td><td>SoC cible supérieur</td></tr></tbody></table><h2 id="auswahlfelder" tabindex="-1">Champs de sélection <a class="header-anchor" href="#auswahlfelder" aria-label="Permalink to &quot;Champs de sélection {#auswahlfelder}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Entité / Traduction</th><th>Options / Usage</th></tr></thead><tbody><tr><td><code>AC-Betriebsmodus</code></td><td>Entrée CA ou sortie CA</td></tr><tr><td><code>DC Anschluss</code></td><td>Entrée/Sortie ou Sortie/Entrée</td></tr><tr><td><code>Hub-Modus</code></td><td>Couplé ou autonome</td></tr><tr><td><code>HEMS-Status</code></td><td>Activé ou désactivé</td></tr><tr><td><code>Auto. Batterieheizung</code></td><td>Activé ou désactivé</td></tr><tr><td><code>Geräte-Sicherungsgruppe</code></td><td>Sélection du groupe de fusibles</td></tr><tr><td><code>Verbindungsart</code></td><td>Cloud, local ou zenSDK (selon l&#39;appareil)</td></tr><tr><td><code>Betriebsmodus</code></td><td>Arrêt, manuel, intelligent, charge uniquement, décharge uniquement, stockage solaire</td></tr><tr><td><code>Bypass-Modus</code></td><td>Automatique, toujours éteint, toujours allumé</td></tr><tr><td><code>Energie Export</code></td><td>Désactivé, autorisé, interdit</td></tr><tr><td><code>Lüftergeschwindigkeit</code></td><td>Automatique, normal, rapide</td></tr></tbody></table><h2 id="schalter-und-buttons" tabindex="-1">Commutateurs et boutons <a class="header-anchor" href="#schalter-und-buttons" aria-label="Permalink to &quot;Commutateurs et boutons {#schalter-und-buttons}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Entité / Traduction</th><th>Usage</th></tr></thead><tbody><tr><td><code>LED</code></td><td>Commande de la LED/lampe</td></tr><tr><td><code>AC Anschluss</code></td><td>Commande de la connexion CA</td></tr><tr><td><code>Bestätigungston</code></td><td>Activer/désactiver le son</td></tr><tr><td><code>Bypass-Modus zurücksetzen</code></td><td>Réinitialiser le bypass automatique</td></tr><tr><td><code>Lüfter</code></td><td>Commande du ventilateur</td></tr><tr><td><code>Reset Verbindung</code></td><td>Relancer la configuration de la connexion/MQTT</td></tr></tbody></table><h2 id="binarsensoren" tabindex="-1">Capteurs binaires <a class="header-anchor" href="#binarsensoren" aria-label="Permalink to &quot;Capteurs binaires {#binarsensoren}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Entité / Traduction</th><th>Fonction</th></tr></thead><tbody><tr><td><code>Hauptschalter</code></td><td>État principal</td></tr><tr><td><code>WLAN-Status</code></td><td>Wi-Fi accessible</td></tr><tr><td><code>Batterieheizung</code></td><td>Chauffage actif</td></tr><tr><td><code>Energiesparmodus</code></td><td>Mode repos / économie</td></tr><tr><td><code>Rückflussstatus</code></td><td>Retour de courant détecté</td></tr><tr><td><code>Lokale Verbindung</code></td><td>Connexion locale active</td></tr><tr><td><code>CT getrennt</code></td><td>Capteur CT déconnecté</td></tr><tr><td><code>Niedrige Temperatur</code></td><td>Basse température détectée</td></tr><tr><td><code>HEMS aktiv</code></td><td>HEMS actif</td></tr></tbody></table><h2 id="gerateabhangigkeit" tabindex="-1">Dépendance aux appareils <a class="header-anchor" href="#gerateabhangigkeit" aria-label="Permalink to &quot;Dépendance aux appareils {#gerateabhangigkeit}&quot;">​</a></h2><p>Les entités sont générées en fonction de la classe de l&#39;appareil, du firmware, du type de connexion et des données transmises via MQTT ou HTTP. L&#39;absence d&#39;une entité ne signifie pas nécessairement qu&#39;il y a une erreur ; il est possible que l&#39;appareil ou la connexion ne fournisse tout simplement pas cette valeur.</p>',17)])])}const p=e(o,[["render",n]]);export{g as __pageData,p as default};
